// Builds the two generated files:
//   public/widget.js            the embeddable widget, bundled and minified
//   src/worker/sites.gen.js     every sites/*.json, checked and normalized
// Wrangler runs this before `wrangler dev` and `wrangler deploy`.
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';
import { normalizeSite } from '../src/shared/site.js';

process.stdout.reconfigure?.({ encoding: 'utf8' });
const root = join(dirname(fileURLToPath(import.meta.url)), '..');

const sites = {};
for (const file of readdirSync(join(root, 'sites')).filter((f) => f.endsWith('.json')).sort()) {
  const site = normalizeSite(JSON.parse(readFileSync(join(root, 'sites', file), 'utf8')), `sites/${file}`);
  if (sites[site.id]) throw new Error(`sites/${file}: id "${site.id}" is already used by another file`);
  sites[site.id] = site;
}
writeFileSync(
  join(root, 'src/worker/sites.gen.js'),
  `// Generated by scripts/build.mjs from sites/*.json. Don't edit; edit the JSON and rebuild.\nexport default ${JSON.stringify(sites, null, 2)};\n`,
);

await build({
  entryPoints: [join(root, 'src/widget/index.js')],
  outfile: join(root, 'public/widget.js'),
  bundle: true,
  minify: true,
  format: 'iife',
  target: ['es2020'],
  legalComments: 'none',
  banner: { js: '/* booking-widget · MIT · github.com/Irnist/booking-widget */' },
  logLevel: 'warning',
});

const size = readFileSync(join(root, 'public/widget.js')).length;
console.log(`built ${Object.keys(sites).length} site(s): ${Object.keys(sites).join(', ')}; widget.js ${(size / 1024).toFixed(1)} KB`);
